    let bytes = 0, deliveredBytes = 0, sourceDone = false, sent = false, hash = null;
    const first = [];
    iterator = stream.body[Symbol.asyncIterator]();
    if (!iterator || typeof iterator.next !== 'function') throw fault('INVALID_RESPONSE_STREAM');
