      const cost = bytes(record).length +
        (component === 'rows' ? bytes(awardItem(record)).length : 0) + 2;
      if (records.length && size + cost > COMPONENT_BUDGET) flush();
      records.push(record); size += cost;
      if (size >= COMPONENT_BUDGET) flush();
