}

const CSV_FIELDS = ['collection', 'feature_id', 'monitoring_location_id', 'time_series_id', 'parameter_code', 'statistic_id', 'time', 'value', 'unit_of_measure', 'approval_status', 'qualifier', 'last_modified', 'source_url', 'source_sha256'];
