      await atomicJson(target, 'operation.json', { ...operation, status: signal?.aborted ? 'INTERRUPTED' : 'FAILED',
        error: { code: error.code ?? 'WATER_DSS_NATIVE_FAILED', message: error.message }, updatedAt: new Date().toISOString() }).catch(() => {});
      throw error;
    }
  });
}
